// Optional Supabase connection. Password and session stay in memory.
let config={url:'https://mhjkqzcyzckhqjdodilj.supabase.co',key:'sb_publishable_ly4g9ZPzqnN27o7Ly07vZQ_EKvMXdVO'},session;
export const status=()=>session?{email:session.user.email,url:config.url}:null;
export function configure(url,key){url=String(url).trim().replace(/\/$/,'');key=String(key).trim();if(!/^https:\/\/[a-z0-9-]+\.supabase\.co$/.test(url))throw Error('Gunakan Project URL https://….supabase.co.');if(!key||key.startsWith('sb_secret_'))throw Error('Gunakan publishable / anon key, bukan secret key.');if(key.startsWith('eyJ')){try{const payload=JSON.parse(atob(key.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));if(payload.role==='service_role')throw Error('service_role');}catch(e){if(e.message==='service_role')throw Error('service_role tidak boleh dipakai di browser. Gunakan anon key.');}}config={url,key};session=null;}
async function request(path,options={},auth=true){if(!config)throw Error('Hubungkan Supabase terlebih dahulu.');if(auth){if(!session)throw Error('Login Supabase terlebih dahulu.');if(session.expires_at*1000<Date.now()+30000){const next=await request('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:JSON.stringify({refresh_token:session.refresh_token}),headers:{'Content-Type':'application/json'}},false);session=await next.json();session.expires_at??=Math.floor(Date.now()/1000)+session.expires_in;}}
const response=await fetch(config.url+path,{...options,headers:{apikey:config.key,...(auth?{Authorization:'Bearer '+session.access_token}:{}),...options.headers},signal:AbortSignal.timeout(90000)});if(!response.ok){let msg;try{const body=await response.json();msg=body.message||body.msg||body.error_description||body.error;}catch{}throw Error('Supabase: '+(msg||response.status));}return response;}
export async function login(email,password){const response=await request('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email,password}),headers:{'Content-Type':'application/json'}},false);session=await response.json();session.expires_at??=Math.floor(Date.now()/1000)+session.expires_in;return status();}
export async function signup(email,password){const response=await request('/auth/v1/signup',{method:'POST',body:JSON.stringify({email,password}),headers:{'Content-Type':'application/json'}},false);const data=await response.json();if(data.access_token){session=data;session.expires_at??=Math.floor(Date.now()/1000)+session.expires_in;}return {signedIn:!!session};}
export async function logout(){try{if(session)await request('/auth/v1/logout',{method:'POST'});}finally{session=null;}}
export async function projects(){const r=await request('/rest/v1/video_projects?select=id,title,updated_at,revision&order=updated_at.desc');return r.json();}
function objectPath(key){return '/storage/v1/object/ruang-adegan/'+key.split('/').map(encodeURIComponent).join('/');}
export async function saveProject(project){const snapshot=structuredClone(project),id=project.id,owner=session?.user.id;if(!owner)throw Error('Login Supabase terlebih dahulu.');const remote=await request('/rest/v1/video_projects?id=eq.'+encodeURIComponent(id)+'&select=revision'),existing=(await remote.json())[0];if(existing&&project.cloudRevision!==existing.revision)throw Error('Proyek di cloud berubah. Buka versi cloud atau simpan sebagai proyek baru agar tidak menimpa perubahan.');
const mediaVersion=crypto.randomUUID();for(const key of ['audio','music'])if(snapshot[key]){const a=snapshot[key],path=`${owner}/${id}/${mediaVersion}/${key}`;await request(objectPath(path),{method:'POST',headers:{'Content-Type':a.type||'application/octet-stream'},body:a.blob});snapshot[key]={name:a.name,type:a.type,duration:a.duration,cloudPath:path};}
snapshot.assets=[];for(const a of project.assets||[]){const path=`${owner}/${id}/${mediaVersion}/${a.id}`;await request(objectPath(path),{method:'POST',headers:{'Content-Type':a.type},body:a.blob});snapshot.assets.push({id:a.id,name:a.name,type:a.type,credit:a.credit||'',cloudPath:path});}
delete snapshot.cloudRevision;const revision=(existing?.revision||0)+1,record={id,owner_id:owner,title:snapshot.title,data:snapshot,revision,updated_at:new Date().toISOString()};const r=await request('/rest/v1/video_projects'+(existing?'?id=eq.'+encodeURIComponent(id)+'&revision=eq.'+existing.revision:''),{method:existing?'PATCH':'POST',headers:{'Content-Type':'application/json',Prefer:'return=representation'},body:JSON.stringify(record)});const rows=await r.json();if(!rows.length)throw Error('Versi cloud berubah saat menyimpan. Buka ulang versi cloud.');return revision;}
export async function openProject(id){const r=await request('/rest/v1/video_projects?id=eq.'+encodeURIComponent(id)+'&select=data,revision');const row=(await r.json())[0];if(!row)throw Error('Proyek cloud tidak ditemukan.');const project=row.data;project.cloudRevision=row.revision;for(const key of ['audio','music'])if(project[key]){const a=project[key];a.blob=await(await request(objectPath(a.cloudPath))).blob();}for(const a of project.assets||[]){a.blob=await(await request(objectPath(a.cloudPath))).blob();}return project;}
export async function saveMp4(project,blob){if(!session)throw Error('Login Supabase terlebih dahulu.');const path=`${session.user.id}/${project.id}/exports/${Date.now()}.mp4`;await request(objectPath(path),{method:'POST',headers:{'Content-Type':'video/mp4'},body:blob});return path;}
